class ModelAction(object):
    ON_RESET = 'Reset'
    ON_REMOVE = 'Remove'
    ON_UPDATE = 'Update'


class ResetEvent(tuple):

    def __new__(self, timestamp):
        return tuple.__new__(self, (ModelAction.ON_RESET, None, timestamp))


class RemoveEvent(tuple):

    def __new__(self, removed, timestamp):
        return tuple.__new__(self, (ModelAction.ON_REMOVE, removed, timestamp))


class UpdateEvent(tuple):

    def __new__(self, updated, timestamp):
        return tuple.__new__(self, (ModelAction.ON_UPDATE, updated, timestamp))
